* @param ScalarCos	Pointer to where the Cos result should be stored
* @param Value  input angles 
*/
template <UE::CFloatingPoint T>
static constexpr inline void SinCos(std::decay_t<T>* ScalarSin, std::decay_t<T>* ScalarCos, T  Value )
{
	// Map Value to y in [-pi,pi], x = 2*pi*quotient + remainder.
	T quotient = (UE_INV_PI*0.5f)*Value;
	if (Value >= 0.0f)
	{
		quotient = (T)((int64)(quotient + 0.5f));
	}
	else
	{
		quotient = (T)((int64)(quotient - 0.5f));
	}
	T y = Value - UE_TWO_PI * quotient;

	// Map y to [-pi/2,pi/2] with sin(y) = sin(Value).
	T sign;
	if (y > UE_HALF_PI)
	{
		y = UE_PI - y;
		sign = -1.0f;
	}
	else if (y < -UE_HALF_PI)
	{
		y = -UE_PI - y;
		sign = -1.0f;
	}
	else
	{
		sign = +1.0f;
	}

	T y2 = y * y;

	// 11-degree minimax approximation
	*ScalarSin = ( ( ( ( (-2.3889859e-08f * y2 + 2.7525562e-06f) * y2 - 0.00019840874f ) * y2 + 0.0083333310f ) * y2 - 0.16666667f ) * y2 + 1.0f ) * y;

	// 10-degree minimax approximation
	T p = ( ( ( ( -2.6051615e-07f * y2 + 2.4760495e-05f ) * y2 - 0.0013888378f ) * y2 + 0.041666638f ) * y2 - 0.5f ) * y2 + 1.0f;
	*ScalarCos = sign*p;
}

inline FVector2D UAlsVector::RadianToDirection(const float Radian)
{
	float Sin, Cos;
	FMath::SinCos(&Sin, &Cos, Radian);

	return {Cos, Sin};
}

inline FVector UAlsVector::RadianToDirectionXY(const float Radian)
{
	float Sin, Cos;
	FMath::SinCos(&Sin, &Cos, Radian);

	return {Cos, Sin, 0.0f};
}

inline FVector2D UAlsVector::AngleToDirection(const float Angle)
{
	return RadianToDirection(FMath::DegreesToRadians(Angle));
}

inline FVector UAlsVector::AngleToDirectionXY(const float Angle)
{
	return RadianToDirectionXY(FMath::DegreesToRadians(Angle));
}

pub fn rig_sin_cos(value: f32) -> (f32, f32) {
    let quotient = (std::f32::consts::FRAC_1_PI * 0.5) * value;
    let quotient = (if value >= 0.0 {
        quotient + 0.5
    } else {
        quotient - 0.5
    }) as i64 as f32;
    let mut y = value - std::f32::consts::TAU * quotient;
    let sign = if y > std::f32::consts::FRAC_PI_2 {
        y = std::f32::consts::PI - y;
        -1.0
    } else if y < -std::f32::consts::FRAC_PI_2 {
        y = -std::f32::consts::PI - y;
        -1.0
    } else {
        1.0
    };
    let y2 = y * y;
    let sine = (((((-2.3889859e-8 * y2 + 2.7525562e-6) * y2 - 0.00019840874) * y2 + 0.0083333310)
        * y2
        - 0.16666667)
        * y2
        + 1.0)
        * y;
    let cosine =
        ((((-2.6051615e-7 * y2 + 2.4760495e-5) * y2 - 0.0013888378) * y2 + 0.041666638) * y2 - 0.5)
            * y2
            + 1.0;
    (sine, sign * cosine)
}

pub fn view_relative_move_input(move_dir: Vec2, view_yaw: f32) -> Vec3 {
    let move_dir = move_dir.clamp_length_max(1.0);
    let source_degrees = (-(view_yaw as f64) - std::f64::consts::FRAC_PI_2).to_degrees() as f32;
    let (sin, cos) = crate::extensions::control_rig_math::rig_sin_cos(source_degrees.to_radians());
    Vec3::new(cos * move_dir.y - sin * move_dir.x, 0.0,
        sin * move_dir.y + cos * move_dir.x)
}

pub fn view_relative_move_direction(move_dir: Vec2, view_yaw: f32) -> Vec3 {
    view_relative_move_input(move_dir, view_yaw).normalize_or_zero()
}

#[test]
fn movement_input_uses_source_float_sine_and_cosine() {
    let yaw = -std::f32::consts::PI * 0.75;
    let actual = view_relative_move_input(Vec2::Y, yaw);
    assert_eq!(actual, Vec3::new(0.7071067094802856, 0.0, 0.7071067690849304));
}

